"""Fresh practice questions with worked solutions, generated by the app.

Every answer is *calculated*, never guessed, so it is correct by construction. Each question
also carries step-by-step working. Levels follow the scaffold: 1 = basic, 2 = standard, 3 = exam-hard.
Questions are reproducible from (generator, level, seed), so a missed one can be shown again.
"""
from __future__ import annotations

import itertools
import random
from fractions import Fraction as F

from .solvers import series_rule

GEN: dict = {}
ALPHA = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def register(gid, name, unit, subtopic, pattern, levels=(1, 2, 3)):
    def deco(fn):
        GEN[gid] = {"id": gid, "name": name, "unit": unit, "subtopic": subtopic, "pattern": pattern,
                    "levels": levels, "fn": fn}
        return fn
    return deco


# ------------------------------------------------------------------ helpers
def frac(x: F) -> str:
    """Exact fraction text, e.g. 1/12 (never a rounded decimal)."""
    return str(x.numerator) if x.denominator == 1 else f"{x.numerator}/{x.denominator}"


def fmt(x) -> str:
    if isinstance(x, int) and not isinstance(x, bool):
        return f"{x:,}" if abs(x) >= 10000 else str(x)
    if isinstance(x, F):
        if x.denominator == 1:
            return f"{x.numerator:,}" if abs(x.numerator) >= 10000 else str(x.numerator)
        v = float(x)
        return f"{v:,.2f}".rstrip("0").rstrip(".")
    if isinstance(x, float):
        return f"{x:,.2f}".rstrip("0").rstrip(".")
    return str(x)


def options(rng, correct, distractors, fmt_fn=fmt):
    """Four distinct options (correct + 3 distractors), shuffled. Returns (texts, answer_index)."""
    seen, opts = {fmt_fn(correct)}, [correct]
    for d in distractors:
        t = fmt_fn(d)
        if t not in seen:
            seen.add(t)
            opts.append(d)
        if len(opts) == 4:
            break
    bump = 1
    while len(opts) < 4:                     # fill with nearby values if needed
        cand = correct + bump if not isinstance(correct, str) else correct + "'" * bump
        if fmt_fn(cand) not in seen:
            seen.add(fmt_fn(cand))
            opts.append(cand)
        bump = -bump if bump > 0 else -bump + 1
    order = list(range(4))
    rng.shuffle(order)
    return [fmt_fn(opts[i]) for i in order], order.index(0)


def make(gid: str, level: int, seed: int, part: int | None = None) -> dict:
    g = GEN[gid]
    rng = random.Random(f"{gid}|{level}|{seed}")
    q = g["fn"](rng, level)
    if isinstance(q, list):                  # a data set with several questions
        part = 0 if part is None else part
        group = q
        q = dict(group[part])
        key = f"gen:{gid}:{level}:{seed}:{part}"
    else:
        key = f"gen:{gid}:{level}:{seed}"
    q.update(key=key, unit=g["unit"], subtopic=q.get("subtopic", g["subtopic"]), pattern=q.get("pattern", g["pattern"]),
             level=level, origin="generated", session="Generated practice", qno=0, display="text", status="ok",
             answer_source="Calculated by the app (always correct)", generator=gid, gen_name=g["name"])
    return q


def from_key(key: str) -> dict | None:
    """Rebuild a generated question from its key (for reviewing mistakes)."""
    try:
        parts = key.split(":")
        gid, level, seed = parts[1], int(parts[2]), int(parts[3])
        part = int(parts[4]) if len(parts) > 4 else None
        return make(gid, level, seed, part) if gid in GEN else None
    except Exception:
        return None


def for_subtopic(subtopic: str) -> list[str]:
    return [g for g, v in GEN.items() if v["subtopic"] == subtopic]


def subtopics_covered() -> set:
    return {v["subtopic"] for v in GEN.values()}


# ================================================================== Unit 5: series
@register("num_series", "Number series", "U5", "U5.1", "numerical")
def g_num_series(rng, level):
    for _ in range(200):
        n = 5 if level == 1 else 6
        if level == 1:
            kind = rng.choice(["ap", "ap", "gp"])
            if kind == "ap":
                a, d = rng.randint(2, 30), rng.choice([2, 3, 4, 5, 6, 7, 8, 9, 11, 12, -3, -4, -5])
                seq = [a + d * i for i in range(n + 1)]
            else:
                a, r = rng.randint(1, 6), rng.choice([2, 3])
                seq = [a * r ** i for i in range(n + 1)]
        elif level == 2:
            kind = rng.choice(["d2", "sq", "alt", "cube"])
            if kind == "d2":
                a, d, dd = rng.randint(1, 20), rng.randint(1, 6), rng.randint(1, 4)
                seq, x, step = [], a, d
                for _i in range(n + 1):
                    seq.append(x)
                    x, step = x + step, step + dd
            elif kind == "sq":
                off, c = rng.randint(1, 6), rng.choice([0, 1, -1, 2, 3])
                seq = [(off + i) ** 2 + c for i in range(n + 1)]
            elif kind == "cube":
                off, c = rng.randint(1, 3), rng.choice([0, 1, -1])
                seq = [(off + i) ** 3 + c for i in range(n + 1)]
            else:
                a, b, d1, d2 = rng.randint(1, 15), rng.randint(20, 40), rng.randint(2, 5), rng.choice([-2, -3, 3, 4])
                seq = [a + d1 * (i // 2) if i % 2 == 0 else b + d2 * (i // 2) for i in range(n + 1)]
        else:
            kind = rng.choice(["kc", "mulinc", "dsq", "d2gp"])
            if kind == "kc":
                k, c, a = rng.choice([2, 3]), rng.choice([1, -1, 2, 3, -2]), rng.randint(1, 6)
                seq = [a]
                for _i in range(n):
                    seq.append(seq[-1] * k + c)
            elif kind == "mulinc":
                a = rng.randint(1, 5)
                seq = [a]
                for i in range(1, n + 1):
                    seq.append(seq[-1] * i + i)
            elif kind == "dsq":
                a, off = rng.randint(1, 20), rng.randint(1, 4)
                seq = [a]
                for i in range(n):
                    seq.append(seq[-1] + (off + i) ** 2)
            else:
                a, d, r = rng.randint(1, 10), rng.randint(1, 3), 2
                seq, step = [a], d
                for _i in range(n):
                    seq.append(seq[-1] + step)
                    step *= r
        if max(abs(x) for x in seq) > 20000:
            continue
        d = [b - a for a, b in zip(seq, seq[1:])]
        plain = len(set(d)) == 1 or (0 not in seq and len({F(b, a) for a, b in zip(seq, seq[1:])}) == 1)
        if level >= 2 and plain:
            continue
        slot = n if level == 1 or rng.random() < 0.6 else rng.randint(1, n - 1)
        ans = seq[slot]
        shown = [str(x) for x in seq[:n]] + ["?"] if slot == n else \
            ["?" if i == slot else str(x) for i, x in enumerate(seq[:n + 1])]
        cands = [ans + 1, ans - 1, ans + 2, ans - 2, ans + (seq[1] - seq[0]), ans * 2 if ans else 3, ans + 10, ans - 10]
        rng.shuffle(cands)
        wrong = []
        for c in cands:
            if c == ans:
                continue
            trial = list(seq[:n + 1]) if slot < n else list(seq[:n]) + [c]
            trial[slot] = c
            if series_rule([F(x) for x in trial]) is None:     # a wrong option must break the pattern
                wrong.append(c)
            if len(wrong) == 3:
                break
        if len(wrong) < 3:
            continue
        full = list(seq[:n + 1]) if slot < n else list(seq[:n]) + [ans]
        steps = series_rule([F(x) for x in full])
        if not steps:
            continue
        opts, ai = options(rng, ans, wrong)
        where = "next term" if slot == n else "missing term"
        return {"text": f"Find the {where} of the series:\n{', '.join(shown)}",
                "options": opts, "answer": ai,
                "steps": ["Write the differences between neighbouring terms first."] + steps +
                         [f"So the {where} is {ans}.", "Check: put it back in; the rule must hold for every term."],
                "hint": "Start with the differences between neighbouring numbers."}
    raise RuntimeError("series generation failed")


@register("letter_series", "Letter series", "U5", "U5.2", "numerical")
def g_letter_series(rng, level):
    def L(i):
        return ALPHA[(i - 1) % 26]
    width = {1: 1, 2: 2, 3: 3}[level]
    starts = [rng.randint(1, 26) for _ in range(width)]
    steps_ = [rng.choice([1, 2, 3, 4, 5, -1, -2, -3]) for _ in range(width)]
    if level == 1:
        steps_ = [rng.choice([1, 2, 3, 4, 5])]
    terms = []
    for t in range(6):
        terms.append("".join(L(starts[p] + steps_[p] * t) for p in range(width)))
    ans = terms[5]
    wrong = set()
    while len(wrong) < 3:
        p = rng.randrange(width)
        d = rng.choice([1, -1, 2, -2])
        w = list(ans)
        w[p] = L(ALPHA.index(ans[p]) + 1 + d)
        w = "".join(w)
        if w != ans:
            wrong.add(w)
    opts, ai = options(rng, ans, sorted(wrong), fmt_fn=str)
    pos_names = ["first", "second", "third"]
    st = ["Write each letter's position: A=1, B=2 … Z=26 (anchor: E=5, J=10, O=15, T=20, Y=25)."]
    for p in range(width):
        nums = [ALPHA.index(t[p]) + 1 for t in terms[:5]]
        st.append(f"{pos_names[p].capitalize()} letters: {' → '.join(t[p] for t in terms[:5])} = "
                  f"{', '.join(map(str, nums))}: each time {'+' if steps_[p] > 0 else '−'}{abs(steps_[p])}"
                  + (" (after Z, start again at A)" if any(n2 < n1 for n1, n2 in zip(nums, nums[1:])) and steps_[p] > 0 else ""))
    st.append(f"Apply the same step once more: {ans}.")
    return {"text": f"Which term comes next in the series?\n{', '.join(terms[:5])}, ?",
            "options": opts, "answer": ai, "steps": st,
            "hint": "Turn letters into numbers (A=1 … Z=26) and look at each position separately."}


WORDS = ["TEACHER", "SCHOOL", "PAPER", "LEARN", "BOOKS", "STUDENT", "COLLEGE", "RESEARCH", "LOGIC", "TABLE",
         "CHART", "MEDIA", "SKILL", "VALUE", "WATER", "EARTH", "GREEN", "LIGHT", "POWER", "MOTION", "NATION",
         "CLASS", "EXAM", "THESIS", "NUMBER", "LETTER", "SERIES", "MARKET", "DIGITAL", "SYSTEM"]


@register("coding", "Coding-decoding", "U5", "U5.3", "numerical")
def g_coding(rng, level):
    w1, w2 = rng.sample(WORDS, 2)
    if level == 1:
        k = rng.choice([1, 2, 3, -1, -2])
        enc = lambda w: "".join(ALPHA[(ALPHA.index(c) + k) % 26] for c in w)
        rule = f"every letter moves {abs(k)} step{'s' if abs(k) > 1 else ''} {'forward' if k > 0 else 'backward'}"
        detail = lambda w: ", ".join(f"{c}→{ALPHA[(ALPHA.index(c) + k) % 26]}" for c in w)
    elif level == 2:
        enc = lambda w: "".join(ALPHA[25 - ALPHA.index(c)] for c in w)
        rule = "each letter is replaced by its opposite letter (A↔Z, B↔Y, C↔X …; positions add up to 27)"
        detail = lambda w: ", ".join(f"{c}({ALPHA.index(c)+1})→{ALPHA[25-ALPHA.index(c)]}({26-ALPHA.index(c)})" for c in w)
    else:
        k = rng.choice([1, 2])
        enc = lambda w: "".join(ALPHA[(ALPHA.index(c) + (k if i % 2 == 0 else -k)) % 26] for i, c in enumerate(w))
        rule = f"letters move +{k} and −{k} alternately (1st +{k}, 2nd −{k}, 3rd +{k} …)"
        detail = lambda w: ", ".join(f"{c}→{ALPHA[(ALPHA.index(c) + (k if i % 2 == 0 else -k)) % 26]}" for i, c in enumerate(w))
    ans = enc(w2)
    wrong = set()
    while len(wrong) < 3:
        w = list(ans)
        i = rng.randrange(len(w))
        w[i] = ALPHA[(ALPHA.index(w[i]) + rng.choice([1, -1, 2])) % 26]
        if rng.random() < 0.3 and len(w) > 3:
            j = (i + 1) % len(w)
            w[i], w[j] = w[j], w[i]
        w = "".join(w)
        if w != ans:
            wrong.add(w)
    opts, ai = options(rng, ans, sorted(wrong), fmt_fn=str)
    return {"text": f"In a certain code, {w1} is written as {enc(w1)}. How is {w2} written in that code?",
            "options": opts, "answer": ai,
            "steps": [f"Compare {w1} and {enc(w1)} letter by letter: {detail(w1)}.", f"Rule: {rule}.",
                      f"Apply it to {w2}: {detail(w2)}.", f"So {w2} is written as {ans}."],
            "hint": "Write the word and its code one under the other and compare each pair of letters."}


# ================================================================== Unit 5: arithmetic
@register("percentage", "Percentage", "U5", "U5.6", "numerical")
def g_percentage(rng, level):
    if level == 1:
        p = rng.choice([5, 10, 12.5, 15, 20, 25, 30, 40, 60, 75])
        base = rng.choice([40, 80, 120, 160, 240, 320, 400, 480, 640, 800])
        ans = F(str(p)) * base / 100
        frac = {12.5: "1/8", 25: "1/4", 20: "1/5", 10: "1/10", 75: "3/4", 40: "2/5", 60: "3/5", 5: "1/20"}.get(p)
        opts, ai = options(rng, ans, [ans * 2, ans / 2, ans + base // 10, F(base) / p])
        return {"text": f"What is {fmt(F(str(p)))}% of {base}?", "options": opts, "answer": ai,
                "steps": [f"{fmt(F(str(p)))}% means {fmt(F(str(p)))} out of 100" + (f", i.e. {frac}." if frac else "."),
                          f"{fmt(F(str(p)))}/100 × {base} = {fmt(ans)}."],
                "hint": "Percent means 'out of 100'."}
    if level == 2:
        old = rng.choice([40, 80, 120, 160, 200, 240, 400, 500, 800])
        pct = rng.choice([10, 20, 25, 30, 40, 50, -10, -20, -25, -40])
        new = old + old * pct // 100
        ans = F(new - old, old) * 100
        trap = F(new - old, new) * 100
        word = "increase" if pct > 0 else "decrease"
        opts, ai = options(rng, abs(ans), [abs(trap), abs(ans) + 5, abs(ans) * 2, abs(ans) - 5], fmt_fn=lambda x: fmt(x) + "%")
        return {"text": f"A value changes from {old} to {new}. What is the percentage {word}?",
                "options": opts, "answer": ai,
                "steps": [f"Change = {new} − {old} = {new - old}.",
                          f"Percentage change = change ÷ OLD value × 100 = {abs(new - old)}/{old} × 100 = {fmt(abs(ans))}%.",
                          f"Trap: dividing by the new value gives {fmt(abs(trap))}%, which is wrong."],
                "hint": "Always divide the change by the original (old) value."}
    a = rng.choice([10, 20, 25, 30, 40, 50])
    b = rng.choice([10, 20, 25, 30, 40, 50])
    up_first = rng.random() < 0.6
    f1, f2 = (F(100 + a, 100), F(100 - b, 100)) if up_first else (F(100 - a, 100), F(100 + b, 100))
    net = (f1 * f2 - 1) * 100
    d1 = f"increases by {a}%" if up_first else f"decreases by {a}%"
    d2 = f"decreases by {b}%" if up_first else f"increases by {b}%"
    naive = (a - b) if up_first else (b - a)
    lab = lambda x: (f"{fmt(abs(x))}% increase" if x > 0 else f"{fmt(abs(x))}% decrease" if x < 0 else "No change")
    opts, ai = options(rng, net, [F(naive), -net if net else F(5), net + 2, net - 2], fmt_fn=lab)
    return {"text": f"A price first {d1} and then {d2}. What is the overall change?",
            "options": opts, "answer": ai,
            "steps": [f"Turn each change into a multiplier: {fmt(f1)} and {fmt(f2)}.",
                      f"Overall multiplier = {fmt(f1)} × {fmt(f2)} = {fmt(f1 * f2)}.",
                      f"{fmt(f1 * f2)} − 1 = {fmt(net / 100)} → {lab(net)}.",
                      f"Trap: simply adding/subtracting the percentages gives {lab(F(naive))}, which ignores that the "
                      "second change acts on the new value."],
            "hint": "Successive percentages multiply; they don't add."}


@register("ratio", "Ratio & proportion", "U5", "U5.5", "numerical")
def g_ratio(rng, level):
    if level == 1:
        a, b = rng.sample([1, 2, 3, 4, 5, 7], 2)
        total = (a + b) * rng.choice([20, 25, 40, 50, 60, 120])
        part = total // (a + b)
        ans = a * part
        opts, ai = options(rng, ans, [b * part, total // a, ans + part, total - part])
        return {"text": f"₹{total} is divided between P and Q in the ratio {a}:{b}. What is P's share?",
                "options": [f"₹{o}" for o in opts], "answer": ai,
                "steps": [f"Total parts = {a} + {b} = {a + b}.", f"One part = {total} ÷ {a + b} = {part}.",
                          f"P gets {a} parts = {a} × {part} = ₹{ans}."],
                "hint": "Add the ratio numbers to get the total number of parts."}
    if level == 2:
        a, b = rng.randint(1, 6), rng.randint(2, 7)
        c, d = rng.randint(2, 7), rng.randint(1, 8)
        A, B, C = a * c, b * c, b * d
        from math import gcd
        g = gcd(gcd(A, B), C)
        A, B, C = A // g, B // g, C // g
        ans = f"{A}:{B}:{C}"
        wrong = [f"{a}:{b}:{d}", f"{a * c}:{b * d}:{c * d}", f"{A}:{C}:{B}", f"{a}:{b * c}:{d}"]
        opts, ai = options(rng, ans, [w for w in wrong if w != ans], fmt_fn=str)
        return {"text": f"If A:B = {a}:{b} and B:C = {c}:{d}, then A:B:C is", "options": opts, "answer": ai,
                "steps": [f"Make the common term B the same in both ratios. B is {b} in the first and {c} in the second.",
                          f"Multiply A:B by {c} → {a * c}:{b * c}; multiply B:C by {b} → {b * c}:{b * d}.",
                          f"Now A:B:C = {a * c}:{b * c}:{b * d}" + (f", which simplifies to {ans}." if g > 1 else ".")],
                "hint": "Make B equal in both ratios first."}
    x, y = rng.choice([10000, 15000, 20000, 25000, 30000]), rng.choice([10000, 20000, 30000, 40000])
    tx, ty = rng.choice([12, 12, 9, 6]), rng.choice([12, 8, 6, 4])
    profit_parts = x * tx + y * ty
    from math import gcd
    g = gcd(x * tx, y * ty)
    rx, ry = x * tx // g, y * ty // g
    total = (rx + ry) * rng.choice([500, 1000, 1200, 1500])
    ans = total * rx // (rx + ry)
    wrong = [total * x // (x + y), total * ry // (rx + ry), total // 2, ans + total // 10]
    opts, ai = options(rng, ans, wrong)
    return {"text": f"P invests ₹{x:,} for {tx} months and Q invests ₹{y:,} for {ty} months in a business. "
                    f"Out of a total profit of ₹{total:,}, what is P's share?",
            "options": [f"₹{o}" for o in opts], "answer": ai,
            "steps": [f"Profit is shared in the ratio of (capital × time).",
                      f"P: {x:,} × {tx} = {x * tx:,};  Q: {y:,} × {ty} = {y * ty:,}.",
                      f"Ratio = {rx}:{ry}.", f"P's share = {rx}/{rx + ry} × {total:,} = ₹{fmt(F(ans))}."],
            "hint": "Multiply each investment by its time before comparing."}


@register("profit_loss", "Profit, loss & discount", "U5", "U5.7", "numerical")
def g_profit(rng, level):
    if level == 1:
        cp = rng.choice([200, 400, 500, 800, 1000, 1200])
        pct = rng.choice([10, 20, 25, 40, -10, -20, -25])
        sp = cp + cp * pct // 100
        ans = F(abs(sp - cp) * 100, cp)
        word = "profit" if pct > 0 else "loss"
        opts, ai = options(rng, ans, [F(abs(sp - cp) * 100, sp), ans + 5, ans * 2, ans - 5], fmt_fn=lambda v: fmt(v) + "%")
        return {"text": f"An article bought for ₹{cp} is sold for ₹{sp}. What is the {word} percentage?",
                "options": opts, "answer": ai,
                "steps": [f"{word.capitalize()} = {abs(sp - cp)}.",
                          f"{word.capitalize()} % = {abs(sp - cp)} ÷ cost price {cp} × 100 = {fmt(ans)}%.",
                          "Remember: profit or loss % is always calculated on the cost price."],
                "hint": "Divide by the cost price, not the selling price."}
    if level == 2:
        cp = rng.choice([400, 500, 600, 800, 1000, 1500, 2000])
        pct = rng.choice([10, 15, 20, 25, 30])
        sp = F(cp * (100 + pct), 100)
        opts, ai = options(rng, sp, [F(cp * 100, 100 - pct), sp + cp // 20, F(cp) + pct, sp - cp // 10])
        return {"text": f"An article costs ₹{cp}. At what price must it be sold to make a {pct}% profit?",
                "options": [f"₹{o}" for o in opts], "answer": ai,
                "steps": [f"SP = CP × (100 + profit%)/100 = {cp} × {100 + pct}/100 = ₹{fmt(sp)}."],
                "hint": "Selling price = cost price increased by the profit percentage."}
    mp = rng.choice([1000, 1200, 1500, 2000, 2400, 3000])
    disc = rng.choice([10, 20, 25])
    prof = rng.choice([8, 10, 20, 25])
    sp = F(mp * (100 - disc), 100)
    cp = sp * 100 / (100 + prof)
    opts, ai = options(rng, cp, [sp * (100 - prof) / 100, F(mp) * (100 - disc - prof) / 100, sp, cp + 50])
    return {"text": f"The marked price of an article is ₹{mp}. After a {disc}% discount the shopkeeper still gains "
                    f"{prof}%. What is the cost price?",
            "options": [f"₹{o}" for o in opts], "answer": ai,
            "steps": [f"Selling price = marked price − {disc}% = {mp} × {100 - disc}/100 = ₹{fmt(sp)}.",
                      f"SP = CP × {100 + prof}/100, so CP = SP × 100/{100 + prof} = {fmt(sp)} × 100/{100 + prof} = ₹{fmt(cp)}.",
                      "Discount is on the marked price; profit is on the cost price."],
            "hint": "First find the selling price after discount; then undo the profit."}


@register("interest", "Simple & compound interest", "U5", "U5.8", "numerical")
def g_interest(rng, level):
    if level == 1:
        P = rng.choice([2000, 5000, 8000, 10000, 12000, 15000])
        R = rng.choice([4, 5, 6, 8, 10, 12])
        T = rng.choice([2, 3, 4, 5])
        si = F(P * R * T, 100)
        opts, ai = options(rng, si, [si + P, F(P * R, 100), si * 2, si - F(P * R, 100)])
        return {"text": f"Find the simple interest on ₹{P:,} at {R}% per annum for {T} years.",
                "options": [f"₹{o}" for o in opts], "answer": ai,
                "steps": [f"SI = P × R × T ÷ 100 = {P:,} × {R} × {T} ÷ 100 = ₹{fmt(si)}."],
                "hint": "SI = P × R × T / 100."}
    if level == 2:
        P = rng.choice([5000, 8000, 10000, 20000])
        R = rng.choice([5, 10, 20])
        A = F(P) * F(100 + R, 100) ** 2
        ci = A - P
        opts, ai = options(rng, ci, [F(P * R * 2, 100), ci + F(P * R, 100), A, ci - 50])
        return {"text": f"Find the compound interest on ₹{P:,} at {R}% per annum for 2 years, compounded yearly.",
                "options": [f"₹{o}" for o in opts], "answer": ai,
                "steps": [f"Amount = P × (1 + R/100)² = {P:,} × ({fmt(F(100 + R, 100))})² = ₹{fmt(A)}.",
                          f"CI = Amount − P = {fmt(A)} − {P:,} = ₹{fmt(ci)}.",
                          f"Compare: simple interest would be ₹{fmt(F(P * R * 2, 100))}; CI is more because interest earns interest."],
                "hint": "Find the amount first, then subtract the principal."}
    R = rng.choice([4, 5, 8, 10, 20])
    diff = rng.choice([16, 25, 40, 50, 64, 100, 160])
    P = F(diff) / (F(R, 100) ** 2)
    opts, ai = options(rng, P, [P / 2, P * 2, F(diff * 100, R), P + 1000])
    return {"text": f"The difference between compound interest and simple interest on a sum for 2 years at {R}% per "
                    f"annum is ₹{diff}. Find the sum.",
            "options": [f"₹{o}" for o in opts], "answer": ai,
            "steps": ["For 2 years: CI − SI = P × (R/100)².",
                      f"{diff} = P × ({R}/100)² = P × {R * R}/10000.",
                      f"P = {diff} × 10000 ÷ {R * R} = ₹{fmt(P)}."],
            "hint": "Use the shortcut CI − SI = P(R/100)² for two years."}


@register("averages", "Averages & ages", "U5", "U5.11", "numerical")
def g_average(rng, level):
    if level == 1:
        nums = [rng.randint(10, 99) for _ in range(5)]
        while sum(nums) % 5:
            nums[0] += 1
        avg = F(sum(nums), 5)
        opts, ai = options(rng, avg, [avg + 1, avg - 2, F(sum(nums), 4), avg + 3])
        return {"text": f"Find the average of {', '.join(map(str, nums))}.", "options": opts, "answer": ai,
                "steps": [f"Sum = {' + '.join(map(str, nums))} = {sum(nums)}.", f"Average = {sum(nums)} ÷ 5 = {fmt(avg)}."],
                "hint": "Add them all, then divide by how many there are."}
    if level == 2:
        n = rng.choice([5, 6, 8, 10])
        avg = rng.choice([40, 45, 50, 60])
        wrong_mark = rng.randint(20, 40)
        right_mark = wrong_mark + n * rng.randint(4, 7)       # keeps the new average a whole number
        new = F(n * avg - wrong_mark + right_mark, n)
        opts, ai = options(rng, new, [F(avg) + (right_mark - wrong_mark), new + 1, F(avg + right_mark, 2), new - 2])
        return {"text": f"The average marks of {n} students is {avg}. Later it was found that one student's marks were "
                        f"entered as {wrong_mark} instead of {right_mark}. What is the correct average?",
                "options": opts, "answer": ai,
                "steps": [f"Wrong total = {n} × {avg} = {n * avg}.",
                          f"Correct total = {n * avg} − {wrong_mark} + {right_mark} = {n * avg - wrong_mark + right_mark}.",
                          f"Correct average = {n * avg - wrong_mark + right_mark} ÷ {n} = {fmt(new)}.",
                          f"Shortcut: average rises by ({right_mark} − {wrong_mark}) ÷ {n} = {fmt(F(right_mark - wrong_mark, n))}."],
                "hint": "Work with totals: total = average × number."}
    from math import gcd
    for _ in range(200):
        a, b = rng.randint(2, 7), rng.randint(2, 9)
        if a == b or gcd(a, b) != 1:
            continue
        k = rng.randint(3, 10)
        n = rng.choice([4, 5, 6, 8, 10])
        A, B = a * k, b * k
        from math import gcd
        c, d = A + n, B + n
        g = gcd(c, d)
        if g == 1 or (c // g, d // g) == (a, b):
            continue
        c, d = c // g, d // g
        opts, ai = options(rng, A, [B, A + n, A - n, a * (k + 1)])
        return {"text": f"The ratio of the present ages of A and B is {a}:{b}. After {n} years the ratio will be {c}:{d}. "
                        f"What is A's present age (in years)?",
                "options": opts, "answer": ai,
                "steps": [f"Let the present ages be {a}x and {b}x.",
                          f"After {n} years: ({a}x + {n}) : ({b}x + {n}) = {c}:{d}.",
                          f"Cross-multiply: {d}({a}x + {n}) = {c}({b}x + {n}) → {d * a}x + {d * n} = {c * b}x + {c * n}.",
                          f"x = {k}, so A = {a} × {k} = {A} years."],
                "hint": "Write the ages as multiples of x using the ratio."}
    raise RuntimeError


@register("speed", "Time, speed & distance", "U5", "U5.9", "numerical")
def g_speed(rng, level):
    if level == 1:
        v = rng.choice([18, 36, 54, 72, 90])
        t = rng.choice([10, 15, 20, 30, 40])
        d = v * 5 // 18 * t
        opts, ai = options(rng, d, [v * t, v * t // 60, d * 2, d + 50])
        return {"text": f"A car moves at {v} km/h. How many metres does it travel in {t} seconds?",
                "options": [f"{o} m" for o in opts], "answer": ai,
                "steps": [f"Convert km/h to m/s: multiply by 5/18 → {v} × 5/18 = {v * 5 // 18} m/s.",
                          f"Distance = speed × time = {v * 5 // 18} × {t} = {d} m."],
                "hint": "Change km/h into m/s first (× 5/18)."}
    if level == 2:
        v_ms = rng.choice([10, 15, 20, 25])
        tlen = rng.choice([100, 150, 200, 250])
        plat = rng.choice([150, 200, 250, 300, 350])
        t = F(tlen + plat, v_ms)
        if t.denominator != 1:
            plat += v_ms - (tlen + plat) % v_ms
            t = F(tlen + plat, v_ms)
        opts, ai = options(rng, t, [F(plat, v_ms), F(tlen, v_ms), t + 5, t * 2], fmt_fn=lambda x: fmt(x) + " s")
        return {"text": f"A train {tlen} m long runs at {v_ms * 18 // 5} km/h. How long does it take to cross a "
                        f"platform {plat} m long?",
                "options": opts, "answer": ai,
                "steps": [f"Speed = {v_ms * 18 // 5} × 5/18 = {v_ms} m/s.",
                          f"To cross a platform the train covers its own length + the platform: {tlen} + {plat} = {tlen + plat} m.",
                          f"Time = {tlen + plat} ÷ {v_ms} = {fmt(t)} seconds."],
                "hint": "Distance = train length + platform length."}
    x, y = rng.choice([(30, 60), (40, 60), (20, 30), (60, 90), (40, 40 * 3 // 2), (30, 45), (36, 45)])
    avg = F(2 * x * y, x + y)
    opts, ai = options(rng, avg, [F(x + y, 2), avg + 2, avg - 3, F(x * y, x + y)], fmt_fn=lambda v: fmt(v) + " km/h")
    return {"text": f"A person goes to a place at {x} km/h and returns by the same route at {y} km/h. "
                    f"What is the average speed for the whole journey?",
            "options": opts, "answer": ai,
            "steps": ["For equal distances, average speed = 2xy ÷ (x + y), not (x + y) ÷ 2.",
                      f"= 2 × {x} × {y} ÷ ({x} + {y}) = {2 * x * y} ÷ {x + y} = {fmt(avg)} km/h.",
                      f"Trap: the simple average {fmt(F(x + y, 2))} km/h is wrong because more time is spent at the slower speed."],
            "hint": "Average speed = total distance ÷ total time."}


@register("time_work", "Time & work", "U5", "U5.10", "numerical")
def g_work(rng, level):
    if level == 1:
        a, b = rng.choice([(10, 15), (12, 24), (20, 30), (6, 12), (15, 30), (12, 36), (18, 36)])
        t = F(a * b, a + b)
        opts, ai = options(rng, t, [F(a + b, 2), t + 2, F(a * b, abs(b - a)), t - 1], fmt_fn=lambda v: fmt(v) + " days")
        return {"text": f"A can finish a job in {a} days and B in {b} days. Working together, how long will they take?",
                "options": opts, "answer": ai,
                "steps": [f"In one day A does 1/{a} and B does 1/{b} of the job.",
                          f"Together: 1/{a} + 1/{b} = {frac(F(1, a) + F(1, b))} of the job per day.",
                          f"Days needed = 1 ÷ {frac(F(1, a) + F(1, b))} = {fmt(t)} days."],
                "hint": "Add the work done per day, not the days."}
    if level == 2:
        a, b, c = rng.choice([(10, 12, 15), (12, 15, 20), (20, 30, 60), (6, 12, 12), (24, 12, 8)])
        r = F(1, a) + F(1, b) + F(1, c)
        t = 1 / r
        opts, ai = options(rng, t, [F(a + b + c, 3), t + 1, t * 2, F(a * b * c, a + b + c)], fmt_fn=lambda v: fmt(v) + " days")
        return {"text": f"A, B and C can do a work in {a}, {b} and {c} days respectively. In how many days can they finish "
                        f"it together?",
                "options": opts, "answer": ai,
                "steps": [f"Work per day: 1/{a} + 1/{b} + 1/{c} = {frac(r)}.", f"Days = 1 ÷ {frac(r)} = {fmt(t)}."],
                "hint": "Shortcut: take the LCM of the days as the total work."}
    f_, e_ = rng.choice([(4, 6), (6, 9), (5, 10), (8, 12), (10, 15), (3, 4)])
    r = F(1, f_) - F(1, e_)
    t = 1 / r
    opts, ai = options(rng, t, [F(f_ * e_, f_ + e_), F(e_ - f_), t / 2, t + 2], fmt_fn=lambda v: fmt(v) + " hours")
    return {"text": f"Pipe A fills a tank in {f_} hours and pipe B empties it in {e_} hours. If both are opened together, "
                    f"in how many hours will the empty tank fill?",
            "options": opts, "answer": ai,
            "steps": [f"Per hour: A fills 1/{f_}; B empties 1/{e_}.",
                      f"Net per hour = 1/{f_} − 1/{e_} = {frac(r)}.", f"Time = 1 ÷ {frac(r)} = {fmt(t)} hours."],
            "hint": "An emptying pipe does negative work."}


@register("direction", "Direction sense", "U5", "U5.4", "numerical", levels=(1, 2))
def g_direction(rng, level):
    triples = [(3, 4, 5), (6, 8, 10), (5, 12, 13), (9, 12, 15), (8, 15, 17)]
    a, b, c = rng.choice(triples)
    d1 = rng.choice(["North", "South", "East", "West"])
    turn = rng.choice(["right", "left"])
    order = ["North", "East", "South", "West"]
    d2 = order[(order.index(d1) + (1 if turn == "right" else -1)) % 4]
    if level == 1:
        opts, ai = options(rng, c, [a + b, abs(b - a), c + 1], fmt_fn=lambda v: f"{v} km")
        return {"text": f"Ravi walks {a} km towards {d1}, then turns {turn} and walks {b} km. How far is he from the start?",
                "options": opts, "answer": ai,
                "steps": [f"After turning {turn} from {d1}, he faces {d2}.",
                          f"The two walks are at right angles, so use Pythagoras: √({a}² + {b}²) = √{a * a + b * b} = {c} km."],
                "hint": "Draw it. Two perpendicular walks make a right-angled triangle."}
    names = {("North", "East"): "North-East", ("East", "North"): "North-East", ("North", "West"): "North-West",
             ("West", "North"): "North-West", ("South", "East"): "South-East", ("East", "South"): "South-East",
             ("South", "West"): "South-West", ("West", "South"): "South-West"}
    ans = names[(d1, d2)]
    wrong = [v for v in ["North-East", "North-West", "South-East", "South-West"] if v != ans]
    opts, ai = options(rng, ans, wrong, fmt_fn=str)
    return {"text": f"Meena walks {a} km towards {d1}, turns {turn} and walks {b} km. In which direction is she now "
                    f"from her starting point?",
            "options": opts, "answer": ai,
            "steps": ["Draw North at the top.", f"First walk goes {d1}; after turning {turn} she walks {d2}.",
                      f"Her final position is {d1.lower()} and {d2.lower()} of the start, i.e. {ans}."],
            "hint": "Draw the path; facing directions change with each turn."}


# ================================================================== Unit 6: logic
TERMS = ["pens", "books", "tables", "chairs", "cups", "lamps", "bags", "boxes", "coins", "keys", "phones", "doors",
         "trees", "birds", "rivers", "stones"]
FORMS = {"A": "All {x} are {y}", "E": "No {x} are {y}", "I": "Some {x} are {y}", "O": "Some {x} are not {y}"}
SQUARE = {("A", True): {"E": False, "I": True, "O": False}, ("A", False): {"E": None, "I": None, "O": True},
          ("E", True): {"A": False, "I": False, "O": True}, ("E", False): {"A": None, "I": True, "O": None},
          ("I", True): {"A": None, "E": False, "O": None}, ("I", False): {"A": False, "E": True, "O": True},
          ("O", True): {"A": False, "E": None, "I": None}, ("O", False): {"A": True, "E": False, "I": True}}
RELATION = {frozenset("AO"): ("contradictory", "they always have opposite truth values"),
            frozenset("EI"): ("contradictory", "they always have opposite truth values"),
            frozenset("AE"): ("contrary", "both cannot be true, but both can be false"),
            frozenset("IO"): ("sub-contrary", "both cannot be false, but both can be true"),
            frozenset("AI"): ("subalternation", "if A is true then I is true; if I is false then A is false"),
            frozenset("EO"): ("subalternation", "if E is true then O is true; if O is false then E is false")}


@register("square", "Square of opposition", "U6", "U6.2", "definition")
def g_square(rng, level):
    x, y = rng.sample(TERMS, 2)
    if level == 1:
        p, q = rng.choice(list(RELATION))
        name, why = RELATION[frozenset((p, q))]
        opts, ai = options(rng, name.capitalize(), [n.capitalize() for n in
                                                    ["contradictory", "contrary", "sub-contrary", "subalternation"] if n != name],
                           fmt_fn=str)
        return {"text": f"What is the relation between '{FORMS[p].format(x=x, y=y)}' and '{FORMS[q].format(x=x, y=y)}' in "
                        f"the traditional square of opposition?",
                "options": opts, "answer": ai,
                "steps": [f"'{FORMS[p].format(x=x, y=y)}' is an {p} proposition; '{FORMS[q].format(x=x, y=y)}' is an {q} proposition.",
                          f"{p} and {q} are {name}: {why}."],
                "hint": "A and E sit on top, I and O below; the diagonals are contradictories."}
    given = rng.choice("AEIO")
    truth = rng.choice([True, False]) if level == 3 else True
    table = SQUARE[(given, truth)]
    ask = rng.choice([k for k in table])
    val = table[ask]
    lab = {True: "True", False: "False", None: "Undetermined (cannot be known)"}
    ans = lab[val]
    opts, ai = options(rng, ans, [v for v in lab.values() if v != ans] + ["Both true and false"], fmt_fn=str)
    name, why = RELATION[frozenset((given, ask))]
    return {"text": f"If '{FORMS[given].format(x=x, y=y)}' is {'true' if truth else 'false'}, then "
                    f"'{FORMS[ask].format(x=x, y=y)}' is:",
            "options": opts, "answer": ai,
            "steps": [f"Given: {given} proposition is {'true' if truth else 'false'}. Asked: the {ask} proposition.",
                      f"{given} and {ask} are {name}: {why}.", f"So the {ask} proposition is {ans.split(' (')[0].lower()}."],
            "hint": "Name the relation first (contradictory, contrary, sub-contrary, subalternation)."}


# ---- syllogisms by checking every possible situation (Venn diagram with 7 regions)
REGIONS = [frozenset(s) for r in range(1, 4) for s in itertools.combinations("SMP", r)]


def _holds(form, x, y, model):
    if form == "A":
        return not any(x in r and y not in r for r in model)
    if form == "E":
        return not any(x in r and y in r for r in model)
    if form == "I":
        return any(x in r and y in r for r in model)
    return any(x in r and y not in r for r in model)


def _models(existential: bool):
    for k in range(0, 1 << 7):
        m = [REGIONS[i] for i in range(7) if k >> i & 1]
        if existential and not all(any(t in r for r in m) for t in "SMP"):
            continue
        yield m


def follows(premises, conclusion, existential):
    """Conclusion follows if it is true in every situation in which all premises are true."""
    for m in _models(existential):
        if all(_holds(f, a, b, m) for f, a, b in premises) and not _holds(*conclusion, m):
            return False
    return True


@register("syllogism", "Syllogisms (which conclusion follows)", "U6", "U6.3", "direct_fact", levels=(1, 2, 3))
def g_syllogism(rng, level):
    names = dict(zip("SMP", rng.sample(TERMS, 3)))
    for _ in range(500):
        if level == 1:
            prem = [(rng.choice("AEI"), "S", "P")]
        else:
            f1, f2 = rng.choice("AEIO"), rng.choice("AE" if level == 2 else "AEIO")
            p1 = (f1, "S", "M") if rng.random() < 0.5 else (f1, "M", "S")
            p2 = (f2, "M", "P") if rng.random() < 0.5 else (f2, "P", "M")
            prem = [p1, p2]
        cands = [(f, a, b) for f in "AEIO" for a, b in (("S", "P"), ("P", "S"))]
        if level == 1:
            cands = [c for c in cands if c != prem[0]]
        good = [c for c in cands if follows(prem, c, True) and follows(prem, c, False)]
        bad = [c for c in cands if not follows(prem, c, True) and not follows(prem, c, False)]
        if not good or len(bad) < 3:
            continue
        ans = rng.choice(good)
        wrong = rng.sample(bad, 3)
        say = lambda c: FORMS[c[0]].format(x=names[c[1]], y=names[c[2]])
        opts, ai = options(rng, say(ans), [say(w) for w in wrong], fmt_fn=str)
        prem_txt = "\n".join(f"Statement {i + 1}: {say(p)}." for i, p in enumerate(prem))
        steps = ["Draw one circle for each term and mark what the statements say: shade empty areas for 'All'/'No', "
                 "put a cross for 'Some'.",
                 f"'{say(ans)}' is true in every picture in which the statements are true, so it definitely follows."]
        for w in wrong:
            steps.append(f"'{say(w)}' does not follow: a picture exists where the statements are true but it is false.")
        if level >= 2:
            steps.append("Quick checks: two negative statements give no conclusion; if a statement is negative the "
                         "conclusion must be negative; the middle term must be 'all'-covered at least once.")
        return {"text": f"{prem_txt}\nWhich conclusion definitely follows?", "options": opts, "answer": ai,
                "steps": steps, "hint": "Draw the circles. Don't add anything the statements don't say."}
    raise RuntimeError("syllogism generation failed")


PRAMANA_SCHOOLS = [("Charvaka", 1, "Pratyaksha"), ("Buddhism", 2, "Pratyaksha and Anumana"),
                   ("Vaisheshika", 2, "Pratyaksha and Anumana"), ("Samkhya", 3, "Pratyaksha, Anumana, Shabda"),
                   ("Yoga", 3, "Pratyaksha, Anumana, Shabda"), ("Nyaya", 4, "Pratyaksha, Anumana, Upamana, Shabda"),
                   ("Prabhakara Mimamsa", 5, "the four of Nyaya + Arthapatti"),
                   ("Bhatta Mimamsa", 6, "the five + Anupalabdhi"), ("Advaita Vedanta", 6, "the five + Anupalabdhi")]
PRAMANA_MEANING = {"Pratyaksha": "perception", "Anumana": "inference", "Upamana": "comparison",
                   "Shabda": "verbal testimony", "Arthapatti": "postulation (implication)",
                   "Anupalabdhi": "non-apprehension"}


@register("pramana", "Pramanas: schools and meanings", "U6", "U6.6", "direct_fact", levels=(1, 2))
def g_pramana(rng, level):
    ladder = ["Charvaka: 1 (Pratyaksha)", "Buddhism, Vaisheshika: 2 (+ Anumana)", "Samkhya, Yoga: 3 (+ Shabda)",
              "Nyaya: 4 (+ Upamana)", "Prabhakara Mimamsa: 5 (+ Arthapatti)",
              "Bhatta Mimamsa, Advaita Vedanta: 6 (+ Anupalabdhi)"]
    if level == 1:
        p = rng.choice(list(PRAMANA_MEANING))
        ans = PRAMANA_MEANING[p]
        opts, ai = options(rng, ans, [v for k, v in PRAMANA_MEANING.items() if k != p], fmt_fn=lambda v: v.capitalize())
        return {"text": f"In Indian logic, the pramana '{p}' means:", "options": opts, "answer": ai,
                "steps": ["The six pramanas: " + "; ".join(f"{k} = {v}" for k, v in PRAMANA_MEANING.items()) + ".",
                          f"So {p} = {ans}."],
                "hint": "Upamana ~ 'upama' (likeness); Anupalabdhi ~ 'not perceived'."}
    school, n, which = rng.choice(PRAMANA_SCHOOLS)
    opts, ai = options(rng, n, [k for k in range(1, 7) if k != n])
    return {"text": f"How many pramanas (means of valid knowledge) does {school} accept?", "options": opts, "answer": ai,
            "steps": ["Learn the ladder (each step adds one pramana):"] + ladder + [f"{school} accepts {n}: {which}."],
            "hint": "Charvaka accepts only one: perception."}


# ================================================================== Unit 7: data interpretation
@register("di_table", "Data interpretation: table set", "U7", "U7.3", "data_interpretation")
def g_di_table(rng, level):
    items = rng.choice([["College A", "College B", "College C", "College D", "College E"],
                        ["Arts", "Science", "Commerce", "Law", "Education"],
                        ["Delhi", "Kerala", "Punjab", "Bihar", "Assam"]])
    years = ["2021", "2022", "2023"]
    what = rng.choice(["students admitted", "books purchased", "research papers published"])
    data = {}
    for it in items:
        base = rng.choice([200, 240, 300, 320, 400, 480, 500, 600, 800])
        g1 = rng.choice([0, 10, 20, 25, 50, -10, -20, -25])
        g2 = rng.choice([0, 10, 20, 25, -10, -20])
        y2 = base + base * g1 // 100
        y3 = y2 + y2 * g2 // 100
        data[it] = [base, y2, y3]
    table = "| " + " | ".join(["Item"] + years) + " |\n|" + "---|" * (len(years) + 1) + "\n" + \
            "\n".join("| " + " | ".join([it] + [str(v) for v in data[it]]) + " |" for it in items)
    group = f"The table shows the number of {what} over three years.\n\n{table}"
    qs = []
    # 1 percentage change
    changed = [i for i in items if data[i][0] != data[i][1]] or items
    it = rng.choice(changed)
    a, b = data[it][0], data[it][1]
    ch = F(b - a, a) * 100
    lab = lambda v: f"{fmt(v)}%"
    opts, ai = options(rng, ch, [F(b - a, b) * 100 if b else ch + 5, ch + 5, -ch if ch else F(10), ch - 5], fmt_fn=lab)
    qs.append({"text": f"What is the percentage change in {what} for {it} from 2021 to 2022?", "options": opts, "answer": ai,
               "steps": [f"{it}: 2021 = {a}, 2022 = {b}.", f"Change = {b - a}.",
                         f"% change = {b - a} ÷ {a} (the earlier year) × 100 = {fmt(ch)}%."]})
    # 2 total in a year
    yi = rng.randrange(3)
    tot = sum(data[i][yi] for i in items)
    opts, ai = options(rng, tot, [tot + 100, tot - 50, sum(data[i][(yi + 1) % 3] for i in items), tot + 20])
    qs.append({"text": f"What is the total number of {what} in {years[yi]}?", "options": opts, "answer": ai,
               "steps": [f"Add the {years[yi]} column: " + " + ".join(str(data[i][yi]) for i in items) + f" = {tot}."]})
    # 3 average of an item
    it = rng.choice(items)
    av = F(sum(data[it]), 3)
    opts, ai = options(rng, av, [F(sum(data[it]), 2), av + 10, F(data[it][0] + data[it][2], 2), av - 10])
    qs.append({"text": f"What is the average number of {what} per year for {it}?", "options": opts, "answer": ai,
               "steps": [f"Sum = {' + '.join(map(str, data[it]))} = {sum(data[it])}.", f"Average = {sum(data[it])} ÷ 3 = {fmt(av)}."]})
    # 4 ratio between two items in a year
    i1, i2 = rng.sample(items, 2)
    yi = rng.randrange(3)
    from math import gcd
    x, y = data[i1][yi], data[i2][yi]
    g = gcd(x, y)
    ans = f"{x // g}:{y // g}"
    opts, ai = options(rng, ans, [f"{y // g}:{x // g}", f"{x // g + 1}:{y // g}", f"{x // g}:{y // g + 1}",
                                  f"{data[i1][(yi + 1) % 3]}:{data[i2][(yi + 1) % 3]}"], fmt_fn=str)
    qs.append({"text": f"What is the ratio of {what} of {i1} to {i2} in {years[yi]}?", "options": opts, "answer": ai,
               "steps": [f"{i1} = {x}, {i2} = {y} in {years[yi]}.", f"{x}:{y} — divide both by {g} → {ans}."]})
    # 5 highest growth 2021 -> 2023 (level 2+), else max in a year
    if level >= 2:
        growth = {i: F(data[i][2] - data[i][0], data[i][0]) for i in items}
        best = max(growth.values())
        if list(growth.values()).count(best) == 1:
            ans = max(growth, key=growth.get)
            others = [i for i in items if i != ans]
            rng.shuffle(others)
            opts, ai = options(rng, ans, others, fmt_fn=str)
            qs.append({"text": f"Which item shows the highest percentage growth from 2021 to 2023?", "options": opts,
                       "answer": ai,
                       "steps": ["% growth = (2023 − 2021) ÷ 2021 × 100 for each:"] +
                                [f"{i}: ({data[i][2]} − {data[i][0]}) ÷ {data[i][0]} = {fmt(growth[i] * 100)}%" for i in items] +
                                [f"Highest: {ans}."]})
    if len(qs) < 5:
        yi = rng.randrange(3)
        col = {i: data[i][yi] for i in items}
        if list(col.values()).count(max(col.values())) == 1:
            ans = max(col, key=col.get)
            others = [i for i in items if i != ans]
            rng.shuffle(others)
            opts, ai = options(rng, ans, others, fmt_fn=str)
            qs.append({"text": f"Which item has the highest number of {what} in {years[yi]}?", "options": opts, "answer": ai,
                       "steps": [f"Look down the {years[yi]} column: " + ", ".join(f"{i} {v}" for i, v in col.items()) +
                                 f". Highest: {ans}."]})
    for q in qs:
        q["group_text"] = group
        q["group_id"] = "gen-di"
        q["hint"] = "Mark exactly which cells you need before calculating."
    return qs


# ================================================================== Unit 8: number systems
@register("number_system", "Number systems & memory units", "U8", "U8.1", "numerical")
def g_numsys(rng, level):
    if level == 1:
        n = rng.randint(9, 127)
        b = bin(n)[2:]
        opts, ai = options(rng, n, [n + 1, n - 1, int(b[::-1], 2) if int(b[::-1], 2) != n else n + 2, n * 2])
        places = [2 ** i for i in range(len(b) - 1, -1, -1)]
        return {"text": f"The binary number {b} equals which decimal number?", "options": opts, "answer": ai,
                "steps": [f"Place values from the right: {', '.join(map(str, reversed(places)))} …",
                          "Add the place values where the digit is 1: " +
                          " + ".join(str(p) for p, d in zip(places, b) if d == "1") + f" = {n}."],
                "hint": "Binary place values double: 1, 2, 4, 8, 16, 32, 64 …"}
    if level == 2:
        n = rng.randint(20, 255)
        h = format(n, "X")
        opts, ai = options(rng, n, [n + 16, n - 1, int(h[::-1], 16) if int(h[::-1], 16) != n else n + 2, n + 10])
        digs = [int(c, 16) for c in h]
        return {"text": f"The hexadecimal number {h} equals which decimal number?", "options": opts, "answer": ai,
                "steps": ["Hex digits: 0–9, then A=10, B=11, C=12, D=13, E=14, F=15. Place values: 1, 16, 256 …",
                          " + ".join(f"{d}×{16 ** (len(digs) - 1 - i)}" for i, d in enumerate(digs)) + f" = {n}."],
                "hint": "Each hex place is worth 16 times the one to its right."}
    unit_from, unit_to, k = rng.choice([("MB", "KB", 1), ("GB", "MB", 1), ("GB", "KB", 2), ("TB", "GB", 1), ("KB", "bytes", 1)])
    q = rng.choice([2, 4, 8, 16])
    ans = q * 1024 ** k
    opts, ai = options(rng, ans, [q * 1000 ** k, q * 1024 ** k // 2, q * 1024 ** (k + 1), ans + 24])
    return {"text": f"{q} {unit_from} is equal to how many {unit_to}? (binary convention)", "options": opts, "answer": ai,
            "steps": ["In the binary convention each unit is 1024 times the one below: bytes → KB → MB → GB → TB.",
                      f"{q} {unit_from} = {q} × 1024" + ("²" if k == 2 else "") + f" = {ans:,} {unit_to}."],
            "hint": "1 KB = 1024 bytes; each step up multiplies by 1024."}


def catalogue():
    """[(gid, name, unit, subtopic, levels)] for the practice menu."""
    return [(g, v["name"], v["unit"], v["subtopic"], v["levels"]) for g, v in GEN.items()]
